using System.Collections.ObjectModel;using System.Windows;using System.Windows.Controls;using System.Windows.Data;using System.Windows.Media;using System.Windows.Threading;
namespace AulaControlTeacher;
public class MainWindow:Window{
 readonly ObservableCollection<Device> devices=new();readonly DataGrid grid=new(){SelectionMode=DataGridSelectionMode.Extended,AutoGenerateColumns=false,IsReadOnly=true,CanUserAddRows=false,RowHeight=46,HeadersVisibility=DataGridHeadersVisibility.Column,GridLinesVisibility=DataGridGridLinesVisibility.Horizontal};readonly TextBlock footer=new(){Foreground=new SolidColorBrush(Color.FromRgb(71,85,105))},online=new(){Foreground=Brushes.White,FontSize=20,FontWeight=FontWeights.Bold};Settings settings;Discovery? discovery;Commands? commands;Registry? registry;readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromSeconds(2)};
 public MainWindow(){Title="AulaControl · Consola docente";Width=1200;Height=720;MinWidth=920;MinHeight=580;WindowStartupLocation=WindowStartupLocation.CenterScreen;Background=new SolidColorBrush(Color.FromRgb(245,247,251));settings=Settings.Load();BuildUi();timer.Tick+=(_,_)=>Refresh();timer.Start();Loaded+=(_,_)=>Configure();Closed+=(_,_)=>discovery?.Dispose();}
 Button B(string s,RoutedEventHandler h){var b=new Button{Content=s,Padding=new Thickness(12,8,12,8),Margin=new Thickness(3)};b.Click+=h;return b;}void BuildUi(){var root=new Grid();root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(84)});root.RowDefinitions.Add(new RowDefinition());root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(34)});var head=new Border{Background=new SolidColorBrush(Color.FromRgb(23,37,84)),Padding=new Thickness(22,10,22,10)};var hg=new Grid();hg.ColumnDefinitions.Add(new ColumnDefinition());hg.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var titles=new StackPanel{VerticalAlignment=VerticalAlignment.Center};titles.Children.Add(new TextBlock{Text="AulaControl",Foreground=Brushes.White,FontSize=28,FontWeight=FontWeights.Bold});titles.Children.Add(new TextBlock{Text="Consola docente · Android",Foreground=new SolidColorBrush(Color.FromRgb(199,210,254)),FontSize=14});hg.Children.Add(titles);var right=new StackPanel{Orientation=Orientation.Horizontal,VerticalAlignment=VerticalAlignment.Center};var badge=new Border{Background=new SolidColorBrush(Color.FromRgb(37,53,111)),CornerRadius=new CornerRadius(9),Padding=new Thickness(14,7,14,7),Margin=new Thickness(0,0,8,0)};var bs=new StackPanel();bs.Children.Add(new TextBlock{Text="EN LÍNEA",Foreground=Brushes.LightGray,FontSize=10,HorizontalAlignment=HorizontalAlignment.Center});bs.Children.Add(online);badge.Child=bs;right.Children.Add(badge);right.Children.Add(B("⚙ Configuración",(_,_)=>ConfigDialog()));Grid.SetColumn(right,1);hg.Children.Add(right);head.Child=hg;root.Children.Add(head);
 var area=new Grid{Margin=new Thickness(18)};area.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});area.RowDefinitions.Add(new RowDefinition());var bar=new WrapPanel{Background=Brushes.White,Margin=new Thickness(0,0,0,12)};bar.Children.Add(B("✓ Todos en línea",(_,_)=>SelectOnline()));bar.Children.Add(B("✉ Mensaje",async(_,_)=>await PromptSend("MESSAGE","Mensaje al estudiante")));bar.Children.Add(B("🌐 Enlace",async(_,_)=>await PromptSend("OPEN_URL","URL completa (https://…)")));bar.Children.Add(B("◫ Solicitar pantalla",async(_,_)=>await Send("REQUEST_SCREEN")));bar.Children.Add(B("▣ Ver en grande",async(_,_)=>await Viewer()));bar.Children.Add(B("▦ Mosaico",(_,_)=>Mosaic()));bar.Children.Add(B("■ Detener pantalla",async(_,_)=>await Send("STOP_SCREEN")));bar.Children.Add(B("↻ Probar conexión",async(_,_)=>await Send("PING")));bar.Children.Add(B("Limpiar offline",(_,_)=>Clean()));area.Children.Add(bar);grid.ItemsSource=devices;AddCol("Estado","Status",110);AddCol("Dispositivo","Name",150);AddCol("Estudiante / usuario","Person",220);AddCol("Curso","CourseText",120);AddCol("ID","Id",140);AddCol("Modelo","Model",180);AddCol("Batería","Battery",80,"{0}%");var ck=new DataGridCheckBoxColumn{Header="Pantalla",Binding=new Binding("Screen"),Width=80};grid.Columns.Add(ck);AddCol("IP","Ip",120);AddCol("Último aviso","SeenText",100);Grid.SetRow(grid,1);area.Children.Add(grid);Grid.SetRow(area,1);root.Children.Add(area);var foot=new Border{Background=new SolidColorBrush(Color.FromRgb(226,232,240)),Padding=new Thickness(14,7,14,7),Child=footer};Grid.SetRow(foot,2);root.Children.Add(foot);Content=root;}
 void AddCol(string h,string b,double w,string? fmt=null){var x=new DataGridTextColumn{Header=h,Binding=new Binding(b),Width=w};if(fmt!=null)((Binding)x.Binding).StringFormat=fmt;grid.Columns.Add(x);}void Configure(){if(string.IsNullOrWhiteSpace(settings.Key)){var k=Ask("Configuración inicial","Clave técnica del aula / establecimiento",true);if(string.IsNullOrWhiteSpace(k)||k.Length<10){footer.Text="Configura una clave técnica para comenzar.";return;}settings.Key=k;settings.Save();}Start();}
 void Start(){discovery?.Dispose();devices.Clear();registry=new Registry(settings.Key);foreach(var x in registry.Load())devices.Add(x);commands=new Commands(settings.Key);discovery=new Discovery(settings.Key);discovery.Seen+=Incoming;try{discovery.Start();footer.Text="Escuchando tablets AulaControl en esta red…";}catch(Exception e){footer.Text="No se pudo abrir UDP 45888: "+e.Message;}}
 void Incoming(Device n)=>Dispatcher.Invoke(()=>{var d=devices.FirstOrDefault(x=>x.Id==n.Id);if(d==null){devices.Add(n);if(!string.IsNullOrWhiteSpace(n.User))SessionLog.Change(n.Id,"",n.User,n.Course);}else{string old=d.User;d.DeviceName=n.DeviceName;d.User=n.User;d.Course=n.Course;d.Model=n.Model;d.Android=n.Android;d.Ip=n.Ip;d.CommandPort=n.CommandPort;d.ScreenPort=n.ScreenPort;d.Battery=n.Battery;d.Screen=n.Screen;d.Seen=DateTime.Now;d.Identity();if(old!=d.User)SessionLog.Change(d.Id,old,d.User,d.Course);}registry?.Save(devices);Refresh();});void Refresh(){foreach(var d in devices)d.Computed();online.Text=devices.Count(x=>DateTime.Now-x.Seen<TimeSpan.FromSeconds(9)).ToString();}
 List<Device> Sel()=>grid.SelectedItems.Cast<Device>().ToList();async Task Send(string a,string v=""){var s=Sel();if(s.Count==0){MessageBox.Show("Selecciona al menos una tablet.","AulaControl");return;}foreach(var d in s){var r=await commands!.Send(d,a,v);if(!r.Item1)footer.Text=$"{d.Name}: {r.Item2}";}if(a=="REQUEST_SCREEN")MessageBox.Show("Android solicitará consentimiento de captura en cada nueva sesión de pantalla.","AulaControl");}async Task PromptSend(string a,string title){var x=Ask(title,a=="MESSAGE"?"Escribe el mensaje":"Escribe la URL completa",false);if(!string.IsNullOrWhiteSpace(x))await Send(a,x);}void SelectOnline(){grid.SelectedItems.Clear();foreach(var d in devices.Where(x=>DateTime.Now-x.Seen<TimeSpan.FromSeconds(9)))grid.SelectedItems.Add(d);}void Clean(){foreach(var d in devices.Where(x=>DateTime.Now-x.Seen>=TimeSpan.FromSeconds(9)).ToList())devices.Remove(d);registry?.Save(devices);}async Task Viewer(){var s=Sel();if(s.Count!=1){MessageBox.Show("Selecciona una tablet.");return;}var d=s[0];if(!d.Screen){await commands!.Send(d,"REQUEST_SCREEN");MessageBox.Show("Acepta la captura en Android y vuelve a abrir el visor.");return;}new ViewerWindow(d,settings.Key){Owner=this}.Show();}void Mosaic(){var x=devices.Where(d=>d.Screen&&DateTime.Now-d.Seen<TimeSpan.FromSeconds(9)).ToList();if(x.Count==0){MessageBox.Show("No hay tablets compartiendo pantalla.");return;}new MosaicWindow(x,settings.Key){Owner=this}.Show();}
 void ConfigDialog(){var k=Ask("Configuración","Clave técnica del aula / establecimiento",true,settings.Key);if(!string.IsNullOrWhiteSpace(k)&&k.Length>=10){settings.Key=k;settings.Save();Start();}}string? Ask(string title,string help,bool password,string initial=""){var w=new Window{Title=title,Width=520,Height=240,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,Owner=this,Background=Brushes.White};var p=new StackPanel{Margin=new Thickness(24)};p.Children.Add(new TextBlock{Text=title,FontSize=22,FontWeight=FontWeights.Bold,Foreground=new SolidColorBrush(Color.FromRgb(23,37,84))});p.Children.Add(new TextBlock{Text=help,Margin=new Thickness(0,8,0,12),TextWrapping=TextWrapping.Wrap});Control input;if(password){var q=new PasswordBox{FontSize=17,Padding=new Thickness(10),Password=initial};input=q;}else{var q=new TextBox{FontSize=17,Padding=new Thickness(10),Text=initial};input=q;}p.Children.Add(input);var ok=B("Aceptar",(_,_)=>w.DialogResult=true);p.Children.Add(ok);w.Content=p;if(w.ShowDialog()!=true)return null;return password?((PasswordBox)input).Password:((TextBox)input).Text.Trim();}
}
